logfire:index/alert:Alert.description:
Manages a Logfire alert.

## Example Usage

<!--Start PulumiCodeChooser -->
```typescript
import * as pulumi from "@pulumi/pulumi";
import * as logfire from "@pydantic/pulumi-logfire";

const exampleProject = new logfire.Project("exampleProject", {});
const exampleChannel = new logfire.Channel("exampleChannel", {config: [{
    type: "webhook",
    format: "auto",
    url: "https://example.com/logfire-webhook",
}]});
const office = new logfire.Channel("office", {config: [{
    type: "webhook",
    format: "auto",
    url: "https://example.com/logfire-office-webhook",
}]});
const officeHours = new logfire.Schedule("officeHours", {
    label: "Office hours",
    timezone: "Europe/London",
    windows: [{
        days: [
            1,
            2,
            3,
            4,
            5,
        ],
        start_time: "09:00",
        end_time: "18:00",
    }],
});
const exampleAlert = new logfire.Alert("exampleAlert", {
    projectId: exampleProject.id,
    description: "Alert on exception spans",
    query: `select
  service_name,
  trace_id,
  otel_status_message as exception_message
from records
where level = 'error'
order by start_timestamp desc
`,
    timeWindow: "1h",
    frequency: "15m",
    environments: ["production"],
    channelAssignments: [
        {
            channel_id: exampleChannel.id,
        },
        {
            channel_id: office.id,
            schedule_id: officeHours.id,
        },
    ],
    notifyWhen: "has_matches",
    active: true,
});
```
